function database(env){if(!env.DB)throw new Error('Database is not configured');return env.DB;}


const DAY=86400000;
const now=()=>Date.now();
class HttpError extends Error{constructor(message,status=400){super(message);this.status=status;}}
const fail=(m,s)=>{throw new HttpError(m,s);};
function clean(v,max=255,required=false){if(typeof v!=='string')v='';v=v.trim();if(v.length>max)fail('A field exceeds its maximum length.');if(required&&!v)fail('Please complete all required fields.');return v;}
function email(v){v=clean(v,254,true).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))fail('Enter a valid email address.');return v;}
function quantity(v){if(!Number.isInteger(v)||v<1||v>10)fail('Quantity must be a whole number from 1 to 10.');return v;}
function totals(items,settings={tax_percent:'5',shipping_type:'free',shipping_flat_rate:'25',free_shipping_min:'500'}){const subtotal=items.reduce((s,p)=>s+p.price_cents*p.quantity,0),tax=Math.round(subtotal*Number(settings.tax_percent||0)/100);const shipping=!subtotal||settings.shipping_type==='free'?0:settings.shipping_type==='free_over'&&subtotal>=Number(settings.free_shipping_min)*100?0:Math.round(Number(settings.shipping_flat_rate||0)*100);return {subtotal,tax,shipping,total:subtotal+tax+shipping};}
let seedPromise;
async function initialize(env){if(!seedPromise)seedPromise=(async()=>{const db=database(env);await db.batch([...catalog.products.map(p=>db.prepare('INSERT INTO products (id,slug,name,category,price_cents,stock,active,condition,image,brand,description) VALUES (?,?,?,?,?,?,1,?,?,?,?) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,name=excluded.name,category=excluded.category,price_cents=excluded.price_cents,condition=excluded.condition,image=excluded.image,brand=excluded.brand,description=excluded.description').bind(p.id,p.slug,p.name,p.category,p.priceCents,p.stock,p.condition,p.image,p.brand,p.description)),...Object.entries({tax_percent:'5',shipping_type:'free',shipping_flat_rate:'25',free_shipping_min:'500'}).map(([k,v])=>db.prepare('INSERT INTO settings (key,value) VALUES (?,?) ON CONFLICT(key) DO NOTHING').bind(k,v))]);})().catch(e=>{seedPromise=undefined;throw e;});return seedPromise;}
async function products(env){return (await database(env).prepare('SELECT * FROM products WHERE active=1 ORDER BY id').all()).results;}
async function limit(request,env,kind,max=30){const ip=request.headers.get('CF-Connecting-IP')||'local';const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ip)))).map(b=>b.toString(16).padStart(2,'0')).join('');const bucket=Math.floor(now()/600000),key=`${kind}:${hash}:${bucket}`;const row=await database(env).prepare('INSERT INTO rate_limits (key,count,expires) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count').bind(key,now()+1200000).first();if(row.count>max)fail('Too many requests. Please wait a few minutes and try again.',429);}
async function session(request,env){const db=database(env),id=request.headers.get('Cookie')?.match(/(?:^|;\s*)digitron_guest=([a-f0-9]{64})(?:;|$)/)?.[1];if(id){const row=await db.prepare('SELECT id FROM sessions WHERE id=? AND expires>?').bind(id,now()).first();if(row)return {id,cookie:null};}await limit(request,env,'session',50);const sid=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b=>b.toString(16).padStart(2,'0')).join('');await db.prepare('INSERT INTO sessions (id,expires,created) VALUES (?,?,?)').bind(sid,now()+30*DAY,now()).run();return {id:sid,cookie:`digitron_guest=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000${new URL(request.url).protocol==='https:'?'; Secure':''}`};}
async function state(env,sid){const db=database(env);const [cart,wish,recent,settings]=await Promise.all([db.prepare('SELECT p.*,c.quantity FROM cart c JOIN products p ON p.id=c.product_id WHERE c.session=? ORDER BY p.id').bind(sid).all(),db.prepare('SELECT product_id FROM wishlist WHERE session=?').bind(sid).all(),db.prepare('SELECT product_id FROM recent WHERE session=? ORDER BY viewed DESC LIMIT 8').bind(sid).all(),db.prepare('SELECT key,value FROM settings').all()]);const config=Object.fromEntries(settings.results.map(r=>[r.key,r.value]));return {items:cart.results,wishlist:wish.results.map(r=>r.product_id),recent:recent.results.map(r=>r.product_id),...totals(cart.results,config)};}
function checkOrigin(request){if(request.headers.get('Origin')!==new URL(request.url).origin)fail('This request must come from this website.',403);if(request.headers.get('Sec-Fetch-Site')==='cross-site')fail('Cross-site request blocked.',403);}
async function limitedBytes(request,max){if(Number(request.headers.get('Content-Length')||0)>max)fail('Request too large.',413);if(!request.body)return new Uint8Array();const reader=request.body.getReader(),chunks=[];let size=0;while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>max){await reader.cancel();fail('Request too large.',413);}chunks.push(value);}const result=new Uint8Array(size);let offset=0;for(const chunk of chunks){result.set(chunk,offset);offset+=chunk.length;}return result;}
async function jsonBody(request){if(!request.headers.get('Content-Type')?.startsWith('application/json'))fail('Expected JSON.',415);const str=new TextDecoder().decode(await limitedBytes(request,16000));try{return JSON.parse(str);}catch{fail('Invalid request.');}}
async function placeOrder(request,env,sid,data){const db=database(env),key=clean(data.request_key,80,true);if(!/^[a-f0-9-]{20,80}$/i.test(key))fail('Invalid checkout reference.');const existing=await db.prepare('SELECT id FROM orders WHERE session=? AND request_key=?').bind(sid,key).first();if(existing)return {ok:true,id:existing.id};const customer={full_name:clean(data.full_name,190,true),email:email(data.email),phone:clean(data.phone,50,true),city:clean(data.city,100,true),address:clean(data.address,1000,true)};if(data.payment_method!=='cash_on_delivery')fail('Only cash on delivery is available.');const s=await state(env,sid);if(!s.items.length)fail('Your cart is empty.');if(!Number.isInteger(data.expected_total)||data.expected_total!==s.total)fail('Your cart total changed. Review it before placing your order.',409);for(const p of s.items){quantity(p.quantity);if(!p.active||p.stock<p.quantity)fail(`${p.name} is no longer available in the requested quantity.`,409);}const id=crypto.randomUUID();const statements=[db.prepare('INSERT INTO orders (id,session,request_key,full_name,email,phone,city,address,subtotal_cents,tax_cents,shipping_cents,total_cents,status,payment,created) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,sid,key,customer.full_name,customer.email,customer.phone,customer.city,customer.address,s.subtotal,s.tax,s.shipping,s.total,'new','cash_on_delivery',now()),...s.items.map(p=>db.prepare('INSERT INTO order_items (order_id,product_id,name,quantity,price_cents) VALUES (?,?,?,?,?)').bind(id,p.id,p.name,p.quantity,p.price_cents)),...s.items.map(p=>db.prepare('DELETE FROM cart WHERE session=? AND product_id=?').bind(sid,p.id))];try{await db.batch(statements);}catch(e){const repeat=await db.prepare('SELECT id FROM orders WHERE session=? AND request_key=?').bind(sid,key).first();if(repeat)return {ok:true,id:repeat.id};if(/stock|price_changed|inactive|cart_changed/i.test(String(e)))fail('Stock or pricing changed during checkout. Please review your cart.',409);throw e;}return {ok:true,id};}
async function validateUpload(file){if(file.size>10*1024*1024)fail('Each attachment must be 10MB or smaller.',413);const ext=file.name.toLowerCase().split('.').at(-1),bytes=new Uint8Array(await file.arrayBuffer());let mime='';if(['jpg','jpeg'].includes(ext)&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255)mime='image/jpeg';if(ext==='png'&&[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v))mime='image/png';if(ext==='pdf'&&String.fromCharCode(...bytes.slice(0,5))==='%PDF-')mime='application/pdf';if(ext==='txt'&&!bytes.includes(0)){try{new TextDecoder('utf-8',{fatal:true}).decode(bytes);mime='text/plain';}catch{}}if(!mime)fail('Only valid JPG, PNG, PDF or UTF-8 TXT files are accepted.');return {mime,bytes};}
async function quote(request,env,sid){if(Number(request.headers.get('Content-Length')||0)>52*1024*1024)fail('Attachments exceed the upload limit.',413);const form=await new Response(await limitedBytes(request,52*1024*1024),{headers:request.headers}).formData();if(form.get('website'))fail('Invalid submission.');const type=clean(form.get('quote_type'),100,true);if(!['gaming-pc','workstation','streaming','part-request','pre-built','upgrade','repair','bulk'].includes(type))fail('Choose a quote type.');const customer={name:clean(form.get('full_name'),255,true),email:email(form.get('email')),phone:clean(form.get('phone'),50),area:clean(form.get('area'),100),message:clean(form.get('message'),5000)};const budget=clean(form.get('budget'),20);if(budget&&(!Number.isFinite(Number(budget))||Number(budget)<0||Number(budget)>10000000))fail('Enter a valid budget.');const useCases=form.getAll('use_case[]').map(v=>clean(v,50));if(useCases.length>8)fail('Too many use cases.');const files=form.getAll('attachments[]').filter(f=>typeof f!=='string'&&f.size>0);if(files.length>5)fail('Attach no more than five files.');const checked=[];for(const f of files)checked.push({file:f,...await validateUpload(f)});if(checked.length&&!env.BUCKET)fail('File uploads are temporarily unavailable.',503);const id=crypto.randomUUID(),uploaded=[],db=database(env);try{for(const f of checked){const attachmentId=crypto.randomUUID(),key=`quotes/${id}/${attachmentId}`;await env.BUCKET.put(key,f.bytes,{httpMetadata:{contentType:f.mime,contentDisposition:'attachment'}});uploaded.push({...f,id:attachmentId,key});}await db.batch([db.prepare('INSERT INTO quotes (id,session,full_name,email,phone,area,quote_type,budget,message,details,created) VALUES (?,?,?,?,?,?,?,?,?,?,?)').bind(id,sid,customer.name,customer.email,customer.phone,customer.area,type,budget,customer.message,JSON.stringify({use_case:useCases}),now()),...uploaded.map(f=>db.prepare('INSERT INTO attachments (id,quote_id,filename,mime,size,object_key) VALUES (?,?,?,?,?,?)').bind(f.id,id,clean(f.file.name,255,true),f.mime,f.file.size,f.key))]);}catch(e){for(const f of uploaded)await env.BUCKET.delete(f.key).catch(()=>{});throw e;}return {ok:true,id,message:'Your quote request has been saved. Keep reference '+id.slice(0,8)+'.'};}
async function api(request,env,sid){const db=database(env),url=new URL(request.url),path=url.pathname;if(request.method==='GET'){if(path==='/api/state')return state(env,sid);if(path==='/api/products')return {products:await products(env),categories:catalog.categories};if(path.startsWith('/api/orders/')){const id=path.split('/').at(-1),order=await db.prepare('SELECT id,full_name,subtotal_cents,tax_cents,shipping_cents,total_cents,status,payment,created FROM orders WHERE id=? AND session=?').bind(id,sid).first();if(!order)fail('Order not found.',404);const items=await db.prepare('SELECT name,quantity,price_cents FROM order_items WHERE order_id=?').bind(id).all();return {order,items:items.results};}fail('Not found.',404);}if(request.method!=='POST')fail('Method not allowed.',405);checkOrigin(request);await limit(request,env,path,path==='/api/quote'?5:path==='/api/checkout'?10:60);if(path==='/api/quote')return quote(request,env,sid);const data=await jsonBody(request);if(!data||typeof data!=='object'||Array.isArray(data))fail('Invalid request.');if(data.website)fail('Invalid submission.');if(path==='/api/cart'){if(data.action==='clear'){await db.prepare('DELETE FROM cart WHERE session=?').bind(sid).run();return state(env,sid);}const id=Number(data.id);if(!Number.isInteger(id))fail('Invalid product.');if(data.action==='remove'){await db.prepare('DELETE FROM cart WHERE session=? AND product_id=?').bind(sid,id).run();return state(env,sid);}if(!['add','set'].includes(data.action))fail('Invalid cart action.');const qty=quantity(data.quantity);const p=await db.prepare('SELECT stock,price_cents FROM products WHERE id=? AND active=1').bind(id).first();if(!p)fail('Product not found.',404);if(p.price_cents<=0)fail('Contact Anom Tech for the current price before adding this product to cart.',409);if(p.stock<qty)fail('This quantity is not available.',409);if(data.action==='add'){const result=await db.prepare('INSERT INTO cart (session,product_id,quantity) VALUES (?,?,?) ON CONFLICT(session,product_id) DO UPDATE SET quantity=cart.quantity+excluded.quantity WHERE cart.quantity+excluded.quantity<=MIN(10,?) RETURNING quantity').bind(sid,id,qty,p.stock).first();if(!result)fail('Quantity exceeds available stock or the 10-item limit.',409);}else await db.prepare('INSERT INTO cart (session,product_id,quantity) VALUES (?,?,?) ON CONFLICT(session,product_id) DO UPDATE SET quantity=excluded.quantity').bind(sid,id,qty).run();return state(env,sid);}if(path==='/api/wishlist'){if(data.action==='clear')await db.prepare('DELETE FROM wishlist WHERE session=?').bind(sid).run();else{const id=Number(data.id);if(!Number.isInteger(id)||!await db.prepare('SELECT id FROM products WHERE id=? AND active=1').bind(id).first())fail('Product not found.',404);if(data.saved===true)await db.prepare('INSERT INTO wishlist (session,product_id) VALUES (?,?) ON CONFLICT DO NOTHING').bind(sid,id).run();else await db.prepare('DELETE FROM wishlist WHERE session=? AND product_id=?').bind(sid,id).run();}return state(env,sid);}if(path==='/api/recent'){const id=Number(data.id);if(!Number.isInteger(id)||!await db.prepare('SELECT id FROM products WHERE id=? AND active=1').bind(id).first())fail('Product not found.',404);await db.prepare('INSERT INTO recent (session,product_id,viewed) VALUES (?,?,?) ON CONFLICT(session,product_id) DO UPDATE SET viewed=excluded.viewed').bind(sid,id,now()).run();return {ok:true};}if(path==='/api/checkout')return placeOrder(request,env,sid,data);if(path==='/api/newsletter'){await db.prepare("CREATE TABLE IF NOT EXISTS newsletter (email TEXT PRIMARY KEY NOT NULL, created INTEGER NOT NULL, status TEXT DEFAULT 'new' NOT NULL)").run();const subscriber=email(data.email);const result=await db.prepare('INSERT INTO newsletter (email,created,status) VALUES (?,?,?) ON CONFLICT(email) DO NOTHING').bind(subscriber,now(),'subscribed').run();const added=Number(result?.meta?.changes||0)>0;return {ok:true,message:added?'Thanks — you are subscribed to Anom Tech updates.':'You are already subscribed to Anom Tech updates.'};}if(path==='/api/chat-lead'){const name=clean(data.name,255,true),mail=email(data.email),phone=clean(data.phone,50),message=clean(data.message,2000,true);await db.prepare('INSERT INTO chat_leads (id,session,name,email,phone,message,product_id,created) VALUES (?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),sid,name,mail,phone,message,Number.isInteger(data.product_id)?data.product_id:null,now()).run();return {ok:true,message:'Your support enquiry has been saved.'};}fail('Not found.',404);}

