function card(p){const cat=categories.find(c=>c.slug===p.category),showBadge=p.badge&&p.badge.toLowerCase()!==p.condition.toLowerCase();return `<article class="product-card group relative rounded-2xl border border-white/10 bg-white/[0.03] overflow-hidden hover:border-brand-accent/50 transition-all duration-500" data-product="${p.id}"><div class="card-image relative aspect-square overflow-hidden bg-gradient-to-br from-white/5 to-transparent"><div class="product-card-badges"><span>${escape(p.condition)}</span>${showBadge?`<span>${escape(p.badge)}</span>`:''}</div><a href="/product/${escape(p.slug)}" aria-label="View ${escape(p.name)}"><img src="/${escape(p.image)}" alt="${escape(p.name)}" class="w-full h-full object-contain p-4 transition-transform duration-700 group-hover:scale-105" loading="lazy"></a><button class="wish-button" data-wish="${p.id}" aria-label="Save ${escape(p.name)} to wishlist" aria-pressed="false">${icon('heart')}</button></div><div class="p-4 product-card-content"><div class="product-card-eyebrow"><span>${escape(cat?.name||p.category)}</span><span class="product-stock is-available">Enquire for availability</span></div><h3 class="font-bold"><a href="/product/${escape(p.slug)}">${escape(p.name)}</a></h3><a class="store-button product-card-details-button" href="/product/${escape(p.slug)}" aria-label="View product details for ${escape(p.name)}">${icon('eye')} View Product Details</a><a class="store-button product-card-price-button" href="/quote#quote-section">${icon('chat-square-text')} Get Price</a><div class="product-card-footer"><strong class="font-bold text-lg">${priceText(p)}</strong></div></div></article>`;}
